def law_cache(facts, query):
    normative_atoms = [
        (
            "contract_states_conditional_reverse_engineering_prohibition",
            (
                "p1",
                "a party acting as Recipient",
                "Confidential Information",
                "decompile, disassemble, reverse engineer, or attempt by any means to reconstruct, identify, or discover source code, underlying ideas, techniques, or algorithms"
            )
        ),
        (
            "contract_states_conditional_reverse_engineering_prohibition",
            (
                "p2",
                "Receiving Party",
                "samples, prototypes or products of the Originating Party",
                "reverse-engineer, analyze, attempt to duplicate, or otherwise attempt to determine the design or method of compiling"
            )
        )
    ]
    applicability_to_exception = {
        (
            "conditional_reverse_engineering_prohibition_applies",
            (
                "p1",
                "a party acting as Recipient",
                "Confidential Information",
                "decompile, disassemble, reverse engineer, or attempt by any means to reconstruct, identify, or discover source code, underlying ideas, techniques, or algorithms"
            )
        ): (
            "p1_advance_written_discloser_authorization_exception_applies",
            (
                "p1",
                "a party acting as Recipient",
                "Discloser",
                "in advance",
                "in writing",
                "specifically authorized otherwise prohibited conduct"
            )
        ),
        (
            "conditional_reverse_engineering_prohibition_applies",
            (
                "p2",
                "Receiving Party",
                "samples, prototypes or products of the Originating Party",
                "reverse-engineer, analyze, attempt to duplicate, or otherwise attempt to determine the design or method of compiling"
            )
        ): (
            "p2_mutually_acceptable_executed_written_agreement_exception_applies",
            (
                "p2",
                "Receiving Party",
                "Originating Party",
                "mutually acceptable to the parties",
                "written agreement",
                "executed by the parties"
            )
        )
    }

    if not isinstance(query, dict):
        return {"answer": None}
    if "predicate" not in query or "arguments" not in query or "positive" not in query:
        return {"answer": None}
    if not isinstance(query["predicate"], str):
        return {"answer": None}
    if not isinstance(query["arguments"], list):
        return {"answer": None}
    if not isinstance(query["positive"], bool):
        return {"answer": None}

    query_base = (query["predicate"], tuple(query["arguments"]))
    query_positive = query["positive"]

    if query_base in normative_atoms:
        if query_positive:
            return {"answer": "Entailment"}
        return {"answer": "Contradiction"}

    if query_base not in applicability_to_exception:
        return {"answer": None}

    required_exception = applicability_to_exception[query_base]
    exception_present = False
    exception_absent = False

    if isinstance(facts, list):
        for record in facts:
            if not isinstance(record, dict) or "atom" not in record:
                continue
            atom = record["atom"]
            if not isinstance(atom, dict):
                continue
            if "predicate" not in atom or "arguments" not in atom or "positive" not in atom:
                continue
            if not isinstance(atom["predicate"], str):
                continue
            if not isinstance(atom["arguments"], list):
                continue
            if not isinstance(atom["positive"], bool):
                continue
            fact_base = (atom["predicate"], tuple(atom["arguments"]))
            if fact_base == required_exception:
                if atom["positive"]:
                    exception_present = True
                else:
                    exception_absent = True

    if exception_present and exception_absent:
        return {"answer": None}
    if not exception_present and not exception_absent:
        return {"answer": None}

    prohibition_applies = exception_absent
    if query_positive == prohibition_applies:
        return {"answer": "Entailment"}
    return {"answer": "Contradiction"}

